declare module 'lodash' {
    export function chunk<T>(array: T[], size?: number): T[][];
    export function flatten<T>(array: T[][]): T[];
    export function range(start: number, end?: number): number[];
    export function shuffle<T>(array: T[]): T[];
    export function sample<T>(array: T[]): T | undefined;
    export function repeat<T>(string: T, n: number): string;
    export function reverse<T>(array: T[]): T[];
    export function sortedUniq<T>(array: T[]): T[];
    export function uniq<T>(array: T[]): T[];
    export function isString(value: any): value is string;
    export function isNumber(value: any): value is number;
    export function isArray(value: any): value is any[];
    export function sum(array: number[]): number;
    export function fill<T>(array: T[], value: T, start?: number, end?: number): T[];
    export function capitalize(string: string): string;
    export function lowerFirst(string: string): string;
    export function upperFirst(string: string): string;
    export function debounce<T extends (...args: any[]) => any>(func: T, wait: number): T;
    export function throttle<T extends (...args: any[]) => any>(func: T, wait: number): T;
    export function cloneDeep<T>(value: T): T;
    export function merge<T, U>(object: T, other: U): T & U;
    export function omit<T extends object, K extends keyof T>(object: T, paths: K[]): Omit<T, K>;
    export function pick<T extends object, K extends keyof T>(object: T, paths: K[]): Pick<T, K>;
    export function get(object: object, path: string | number | (string | number)[], defaultValue?: any): any;
    export function set(object: object, path: string | number | (string | number)[], value: any): object;
    export function has(object: object, path: string | number | (string | number)[]): boolean;
    export function size(collection: object | any[] | string): number;
    export function keys(object: object): string[];
    export function values(object: object): any[];
    export function entries(object: object): [string, any][];
    export function fromPairs(pairs: [string, any][]): object;
    export function flatMap<T, R>(collection: T[], iteratee: (value: T) => R | R[]): R[];
    export function flatMapDeep<T, R>(collection: T[], iteratee: (value: T) => R | R[]): R[];
    export function map<T, R>(collection: T[], iteratee: (value: T) => R): R[];
    export function filter<T>(collection: T[], predicate: (value: T) => boolean): T[];
    export function find<T>(collection: T[], predicate: (value: T) => boolean): T | undefined;
    export function findIndex<T>(collection: T[], predicate: (value: T) => boolean): number;
    export function forEach<T>(collection: T[], iteratee: (value: T) => void): T[];
    export function forEachRight<T>(collection: T[], iteratee: (value: T) => void): T[];
    export function reduce<T, R>(collection: T[], iteratee: (accumulator: R, value: T) => R, initialValue: R): R;
    export function every<T>(collection: T[], predicate: (value: T) => boolean): boolean;
    export function some<T>(collection: T[], predicate: (value: T) => boolean): boolean;
    export function includes(collection: string | any[], value: any, fromIndex?: number): boolean;
    export function indexOf<T>(array: T[], value: T, fromIndex?: number): number;
    export function lastIndexOf<T>(array: T[], value: T, fromIndex?: number): number;
    export function groupBy<T>(collection: T[], iteratee: (value: T) => string): Record<string, T[]>;
    export function countBy<T>(collection: T[], iteratee: (value: T) => string): Record<string, number>;
    export function sortBy<T>(collection: T[], iteratees: ((value: T) => any)[]): T[];
    export function orderBy<T>(collection: T[], iterates: ((value: T) => any)[], orders: ('asc' | 'desc')[]): T[];
    export function uniqBy<T>(array: T[], iteratee: (value: T) => any): T[];
    export function drop<T>(array: T[], n?: number): T[];
    export function dropRight<T>(array: T[], n?: number): T[];
    export function take<T>(array: T[], n?: number): T[];
    export function takeRight<T>(array: T[], n?: number): T[];
    export function initial<T>(array: T[]): T[];
    export function tail<T>(array: T[]): T[];
    export function slice<T>(array: T[], start?: number, end?: number): T[];
    export function remove<T>(array: T[], predicate: (value: T, index: number) => boolean): T[];
}
